"""Per-dial config, generated by scripts/provision.py into config.json.

Copy this file's defaults only for a bench test; a provisioned dial reads
config.json from flash. Never commit real Wi-Fi passwords.
"""
import json

DEFAULTS = {
    "room_id": "living",
    "room_name": "Living",
    "dial_id": "sundial-living-01",
    "wifi_ssid": "YOUR_WIFI_SSID",
    "wifi_password": "YOUR_WIFI_PASSWORD",
    "hub_url": "http://192.168.1.10:8000",
    "mqtt_broker": "",
}

try:
    with open("config.json") as _f:
        CONFIG = dict(DEFAULTS)
        CONFIG.update(json.load(_f))
except Exception:
    CONFIG = dict(DEFAULTS)
